import { cn } from "@/lib/utils";

/**
 * The portal mark: a ring four fifths full (the 80% attendance line) with an
 * amber tick where it stops. Matches app/icon.svg (generated by scripts/build-icons.mjs).
 */
export function Logo({ className }: { className?: string }) {
  const r = 18;
  const c = 2 * Math.PI * r;
  return (
    <svg viewBox="0 0 64 64" className={cn("h-8 w-8", className)} role="img" aria-label="Student Portal">
      <rect width="64" height="64" rx="16" className="fill-primary" />
      <g className="stroke-primary-foreground" fill="none" strokeWidth={9}>
        <circle cx="32" cy="32" r={r} strokeOpacity={0.22} />
        <circle
          cx="32"
          cy="32"
          r={r}
          strokeLinecap="round"
          strokeDasharray={`${(c * 0.75).toFixed(2)} ${c.toFixed(2)}`}
          transform="rotate(-90 32 32)"
        />
      </g>
      <line x1="7.5" y1="32" x2="19" y2="32" stroke="#e09f1f" strokeWidth={5} strokeLinecap="round" />
    </svg>
  );
}
